+// Brannock keeps UK time: GMT in winter, and one hour ahead (BST) in summer.
+// Crews plan their shifts on the depot wall clock, so the queue speaks Brannock time.
+const BRANNOCK_TIME_ZONE = "Europe/London";
+
+const wallClockFormat = new Intl.DateTimeFormat("en-GB", {
+  timeZone: BRANNOCK_TIME_ZONE,
+  year: "numeric",
+  month: "2-digit",
+  day: "2-digit",
+  hour: "2-digit",
+  minute: "2-digit",
+  second: "2-digit",
+  hourCycle: "h23",
+});
+
+const labelFormat = new Intl.DateTimeFormat("en-GB", {
+  timeZone: BRANNOCK_TIME_ZONE,
+  weekday: "short",
+  day: "numeric",
+  month: "short",
+  hour: "2-digit",
+  minute: "2-digit",
+});
+
+// The Brannock wall clock at one moment, written as if it were UTC.
+// For example, 12:00 UTC in July reads 13:00 on the wall, so this gives 13:00.
+export function toBrannockClock(isoTime: string): number {
+  const moment = new Date(isoTime);
+  const pieces = wallClockFormat.formatToParts(moment);
+  const clock = Object.fromEntries(pieces.map((piece) => [piece.type, Number(piece.value)]));
+  const timeOfDay = [clock.hour, clock.minute, clock.second, moment.getUTCMilliseconds()];
+  return Date.UTC(clock.year, clock.month - 1, clock.day, ...timeOfDay);
+}
+
+// From a Brannock wall clock time back to a real moment, as an ISO time in UTC.
+export function fromBrannockClock(wallClock: number): string {
+  const asIfUtc = new Date(wallClock).toISOString();
+  const hoursAhead = toBrannockClock(asIfUtc) - wallClock;
+  return new Date(wallClock - hoursAhead).toISOString();
+}
+
+// What a crew reads on the queue screen, for example "Sun 25 Oct, 14:05".
+export function brannockLabel(isoTime: string): string {
+  return labelFormat.format(new Date(isoTime));
+}
